/*
 * MIXCLOUD — NEON AFTERHOURS / fresh Stylish theme
 * Plain CSS compatible with Userstyles.org legacy parser
 */

/* 1. Palette and Mixcloud's named design tokens. */
:root,
:root[data-theme] {
  color-scheme: dark !important;
  --vw-bg: #0d0918;
  --vw-panel: #171026;
  --vw-raised: #211533;
  --vw-hover: #35204f;
  --vw-active: #183c50;
  --vw-border: #68488b;
  --vw-text: #eadcff;
  --vw-muted: #c6aedb;
  --vw-cyan: #7cecf5;
  --vw-pink: #ff9de2;
  --vw-blue: #9dbfff;
  --vw-purple: #c9a4ff;
  --vw-button: #562583;
  --vw-button-hover: #5f2b8a;

  --color-core-primary: var(--vw-button) !important;
  --color-core-primary-hover: var(--vw-button-hover) !important;
  --color-core-secondary: #234e69 !important;
  --color-core-secondary-hover: #2a5c79 !important;
  --color-core-brand: #7739bb !important;
  --color-core-pro: #7739bb !important;
  --color-core-premium: #59306d !important;
  --color-core-premium-hover: #6b3b80 !important;
  --color-core-subtle: var(--vw-border) !important;
  --color-core-success: #143b36 !important;
  --color-core-warning: #49321f !important;
  --color-core-info: #1d3152 !important;
  --color-core-error: #4b193c !important;
  --color-core-disabled: #392c49 !important;
  --color-core-important: #842e66 !important;
  --color-core-important-hover: #9a3878 !important;
  --color-core-confirm: #21564f !important;
  --color-core-confirm-hover: #28665e !important;
  --color-core-black: #080511 !important;
  --color-core-black50: #080511b3 !important;

  --color-text-primary: var(--vw-text) !important;
  --color-text-secondary: var(--vw-muted) !important;
  --color-text-tertiary: var(--vw-text) !important;
  --color-text-fixed-muted: var(--vw-muted) !important;
  --color-text-fixed-highlight: var(--vw-pink) !important;
  --color-text-fixed-on-tint: var(--vw-text) !important;
  --color-text-on-brand: var(--vw-text) !important;
  --color-text-hover: var(--vw-pink) !important;
  --color-text-link: var(--vw-cyan) !important;
  --color-text-link-hover: var(--vw-pink) !important;
  --color-text-on-cta: var(--vw-text) !important;
  --color-text-on-hero: var(--vw-text) !important;
  --color-text-marketing-body: var(--vw-muted) !important;

  --color-surface-primary: var(--vw-bg) !important;
  --color-surface-primary-hover: var(--vw-hover) !important;
  --color-surface-secondary: var(--vw-panel) !important;
  --color-surface-secondary-hover: var(--vw-hover) !important;
  --color-surface-tertiary: var(--vw-raised) !important;
  --color-surface-tertiary-hover: var(--vw-hover) !important;
  --color-surface-subtle: #21153399 !important;
  --color-surface-subtle-hover: #35204fcc !important;
  --color-surface-raised: var(--vw-raised) !important;
  --color-surface-cta: var(--vw-button) !important;
  --color-surface-cta-hover: var(--vw-button-hover) !important;
  --color-surface-hero: #24103d !important;
  --color-surface-hero-action: #234e69 !important;
  --color-surface-hero-action-hover: #2a5c79 !important;
  --color-surface-skeleton: #281d3b !important;
  --color-surface-inset: #100b1e !important;
  --color-surface-fixed: var(--vw-panel) !important;
  --color-surface-fixed-hover: var(--vw-hover) !important;
  --color-surface-fixed-raised: var(--vw-raised) !important;
  --color-surface-fixed-muted: #49365f !important;
  --color-surface-fixed-pale: var(--vw-raised) !important;
  --color-surface-fixed-highlight: #302047 !important;
  --color-border-primary: #38264e !important;
  --color-border-secondary: var(--vw-border) !important;
  --color-brand-gradient-end: #352465 !important;

  --color-waveform-active-default: #9274b3 !important;
  --color-waveform-active-listened: var(--vw-pink) !important;
  --color-waveform-active-interacted: #7cecf5cc !important;
  --color-waveform-initial-default: #806393 !important;
  --color-waveform-initial-listened: var(--vw-blue) !important;
  --color-waveform-initial-interacted: #9dbfffcc !important;
  --rgb-surface-primary: 13, 9, 24 !important;
  --rgb-surface-tertiary: 33, 21, 51 !important;
}

