/* 3. Page, copy, links, and selection. */
html, body {
  background: var(--vw-bg) !important;
  color: var(--vw-text) !important;
}

h1, h2, h3, h4, h5, h6 { color: var(--vw-text) !important; }
body a { color: var(--vw-cyan) !important; }
body a:visited { color: var(--vw-purple) !important; }
body a:hover, body a:focus-visible {
  color: var(--vw-pink) !important;
  background-color: var(--vw-hover) !important;
  background-image: none !important;
}
::selection { background: #563174 !important; color: var(--vw-cyan) !important; }

/* 4. Buttons */
button, [role="button"], [data-sentry-component="Button"] {
  color: var(--vw-text) !important;
  background-color: var(--vw-button) !important;
  background-image: none !important;
  border-color: var(--vw-border) !important;
  text-shadow: none !important;
}
button:hover, button:focus-visible,
[role="button"]:hover, [role="button"]:focus-visible,
[data-sentry-component="Button"]:hover, [data-sentry-component="Button"]:focus-visible {
  color: var(--vw-text) !important;
  background-color: var(--vw-button-hover) !important;
  background-image: none !important;
  border-color: var(--vw-pink) !important;
}
button span, button svg,
[role="button"] span, [role="button"] svg,
[data-sentry-component="Button"] span, [data-sentry-component="Button"] svg,
a:hover span, a:hover svg,
a:focus-visible span, a:focus-visible svg {
  color: inherit !important;
}
button > span, [role="button"] > span, [data-sentry-component="Button"] > span {
  background-color: transparent !important;
}
button:disabled, button[aria-disabled="true"], [role="button"][aria-disabled="true"] {
  color: var(--vw-muted) !important;
  background: #392c49 !important;
  opacity: 1 !important;
}

/* 5. Navigation, tabs, and toggles */
a[aria-current="page"],
[role="tab"][aria-selected="true"],
button[aria-pressed="true"],
[role="option"][aria-selected="true"] {
  color: var(--vw-cyan) !important;
  background-color: var(--vw-active) !important;
  background-image: none !important;
  border-color: var(--vw-cyan) !important;
}

/* 6. Popups, dropdowns, tooltips, and dialogs */
[role="menu"], [role="listbox"], [role="dialog"], [role="tooltip"],
dialog, [popover], .react-datepicker, .react-datepicker__header,
.react-datepicker__time, .react-datepicker__month-container {
  color: var(--vw-text) !important;
  background: var(--vw-panel) !important;
  border-color: var(--vw-border) !important;
  box-shadow: 0 12px 36px #06030dcc, 0 0 18px #c15eff26 !important;
}
[role="menu"] > div, [role="listbox"] > div, [role="dialog"] > div {
  color: var(--vw-text) !important;
  background-color: var(--vw-panel) !important;
  background-image: none !important;
}
[role="menu"] ul, [role="menu"] li,
[role="listbox"] ul, [role="listbox"] li {
  background-color: transparent !important;
  color: var(--vw-text) !important;
}
[role="menu"] a, [role="menu"] button, [role="menu"] [role="menuitem"],
[role="listbox"] a, [role="listbox"] button, [role="listbox"] [role="option"] {
  color: var(--vw-cyan) !important;
  background-color: transparent !important;
  background-image: none !important;
}
[role="menu"] a:hover, [role="menu"] button:hover, [role="menu"] [role="menuitem"]:hover,
[role="listbox"] a:hover, [role="listbox"] button:hover, [role="listbox"] [role="option"]:hover,
[role="menuitem"][data-highlighted], [role="option"][data-highlighted],
.react-datepicker__year-option:hover,
.react-datepicker__month-option:hover,
.react-datepicker__month-year-option:hover {
  color: var(--vw-pink) !important;
  background: var(--vw-hover) !important;
}
[role="menu"] [aria-selected="true"],
[role="listbox"] [aria-selected="true"] {
  color: var(--vw-cyan) !important;
  background: var(--vw-active) !important;
}
[role="menu"] span, [role="menu"] svg,
[role="listbox"] span, [role="listbox"] svg {
  color: inherit !important;
}
dialog::backdrop { background: #080511c9 !important; }
[role="alert"], [data-sentry-component="ErrorMessage"] {
  color: var(--vw-pink) !important;
}

/* 7. Search, form fields, and inputs */
input:not([type="checkbox"]):not([type="radio"]):not([type="range"]):not([type="submit"]):not([type="button"]),
textarea, select, [contenteditable="true"] {
  color: var(--vw-text) !important;
  background: #100b1e !important;
  border-color: var(--vw-border) !important;
  caret-color: var(--vw-pink) !important;
}
input::placeholder, textarea::placeholder { color: var(--vw-muted) !important; opacity: 1 !important; }
select option, select optgroup { background: var(--vw-panel) !important; color: var(--vw-text) !important; }
select option:checked { background: var(--vw-hover) !important; color: var(--vw-cyan) !important; }
input:-webkit-autofill,
input:-webkit-autofill:hover,
input:-webkit-autofill:focus {
  -webkit-text-fill-color: var(--vw-text) !important;
  -webkit-box-shadow: 0 0 0 1000px #100b1e inset !important;
  caret-color: var(--vw-pink) !important;
}
input[type="checkbox"], input[type="radio"], input[type="range"] {
  accent-color: var(--vw-pink) !important;
}

/* 8. Unified header */
header, [role="banner"], [data-sentry-component="TopNav"] {
  color: var(--vw-cyan) !important;
  background: #120b21 !important;
  border-color: var(--vw-border) !important;
}
header a, header button, header [role="button"], header [data-sentry-component="Label"], header svg,
[role="banner"] a, [role="banner"] button, [role="banner"] [role="button"], [role="banner"] [data-sentry-component="Label"], [role="banner"] svg,
[data-sentry-component="TopNav"] a, [data-sentry-component="TopNav"] button, [data-sentry-component="TopNav"] [role="button"], [data-sentry-component="Label"], [data-sentry-component="TopNav"] svg {
  color: var(--vw-cyan) !important;
}
header a:hover, header button:hover,
[role="banner"] a:hover, [role="banner"] button:hover,
[data-sentry-component="TopNav"] a:hover, [data-sentry-component="TopNav"] button:hover {
  color: var(--vw-pink) !important;
  background: var(--vw-hover) !important;
}
header a span, header button span, header svg,
[role="banner"] a span, [role="banner"] button span,
[data-sentry-component="TopNav"] a span, [data-sentry-component="TopNav"] button span {
  color: inherit !important;
}
svg[data-sentry-component="CriticalSpriteIcon"]:not([fill="none"]),
svg[data-testid$="-icon"]:not([fill="none"]) {
  fill: currentColor !important;
}

/* 9. Glowing logo */
svg[data-sentry-element="MixcloudLogo"],
svg[data-sentry-component="LogoMedium"] {
  color: var(--vw-cyan) !important;
  fill: currentColor !important;
  filter: brightness(0) saturate(100%) invert(88%) sepia(69%)
          saturate(596%) hue-rotate(120deg) brightness(103%) contrast(102%)
          drop-shadow(0 0 4px #7cecf5a6)
          drop-shadow(0 0 11px #d76aff80) !important;
}

/* 10. Focus and scrollbar */
a:focus-visible, button:focus-visible, input:focus-visible,
textarea:focus-visible, select:focus-visible, [tabindex]:focus-visible, [role="button"]:focus-visible {
  outline: 2px solid var(--vw-cyan) !important;
  outline-offset: 3px !important;
}
* { scrollbar-color: #79539f var(--vw-bg); }
::-webkit-scrollbar { background: var(--vw-bg); }
::-webkit-scrollbar-thumb { background: #79539f; border: 3px solid var(--vw-bg); border-radius: 10px; }
::-webkit-scrollbar-thumb:hover { background: #ab75cb; }
